CREATE OR REPLACE FUNCTION public.maria_ultimas_vendas(p_limite integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_empresa_id uuid;
  v_resultado jsonb;
  v_limite integer;
begin
  v_empresa_id := private.empresa_id_ativa();

  if not private.perm('pdv') then
    raise exception 'Usuário sem permissão para consultar vendas.';
  end if;

  v_limite := greatest(1, least(coalesce(p_limite,10),50));

  select coalesce(
    jsonb_agg(to_jsonb(x) order by x.criado_em desc),
    '[]'::jsonb
  )
  into v_resultado
  from (
    select
      numero_venda,
      total,
      forma_pagamento,
      criado_em
    from public.vendas
    where empresa_id = v_empresa_id
    order by criado_em desc
    limit v_limite
  ) x;

  return v_resultado;
end;
$function$

CREATE OR REPLACE FUNCTION public.maria_uso_atual()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_emp uuid := private.exigir_empresa_ativa();
  v_cfg jsonb := private.maria_config_efetiva(v_emp);
  v_mes date := private.maria_mes_ref();
  u public.maria_uso_mensal%rowtype;
  v_li integer := nullif(v_cfg->>'limite_interacoes_mes','')::integer;
  v_lt bigint  := nullif(v_cfg->>'limite_tokens_mes','')::bigint;
  v_lc numeric := nullif(v_cfg->>'limite_custo_usd_mes','')::numeric;
  v_pct numeric;
begin
  select * into u from public.maria_uso_mensal where empresa_id = v_emp and mes_ref = v_mes;
  v_pct := greatest(
     case when v_li > 0 then coalesce(u.interacoes,0)::numeric / v_li else 0 end,
     case when v_lt > 0 then coalesce(u.tokens_total,0)::numeric / v_lt else 0 end,
     case when v_lc > 0 then coalesce(u.custo_usd,0) / v_lc else 0 end);
  return jsonb_build_object(
    'ativa', (v_cfg->>'ativa')::boolean, 'plano', v_cfg->>'plano_nome',
    'interacoes', coalesce(u.interacoes,0), 'limite_interacoes', v_li,
    'tokens_total', coalesce(u.tokens_total,0), 'limite_tokens', v_lt,
    'percentual_usado', case when v_li is null and v_lt is null and v_lc is null then null else round(least(v_pct,9.99)*100, 1) end,
    'ultimo_uso', u.ultimo_uso);
end $function$

CREATE OR REPLACE FUNCTION public.maria_uso_finalizar(p_interacao_id uuid, p_status text, p_operacao text, p_chamadas integer, p_tokens_entrada bigint, p_tokens_saida bigint, p_tokens_cached bigint, p_tokens_total bigint, p_modelo text, p_ferramentas text[], p_erro_codigo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_emp  uuid;
  v_uid  uuid := auth.uid();
  i      public.maria_interacoes%rowtype;
  v_preco public.maria_precos_modelo%rowtype;
  v_in bigint := greatest(coalesce(p_tokens_entrada,0),0);
  v_out bigint := greatest(coalesce(p_tokens_saida,0),0);
  v_cached bigint;
  v_total bigint;
  v_custo numeric;
  v_conta boolean;
  v_cham integer := greatest(coalesce(p_chamadas,0),0);
begin
  perform private.maria_exigir_servidor();
  v_emp := private.exigir_empresa_ativa();
  if p_status not in ('concluida','erro') then raise exception 'Status inválido.'; end if;

  select * into i from public.maria_interacoes
   where id = p_interacao_id and empresa_id = v_emp and user_id = v_uid for update;
  if not found then raise exception 'Interação não encontrada.'; end if;
  if i.status <> 'reservada' then
    return jsonb_build_object('ok', true, 'ja_finalizada', true, 'custo_usd', i.custo_usd);
  end if;

  v_cached := least(greatest(coalesce(p_tokens_cached,0),0), v_in);          -- cached é subconjunto do prompt
  v_total  := greatest(coalesce(p_tokens_total, v_in + v_out), v_in + v_out); -- nunca abaixo da soma
  v_preco  := private.maria_preco_vigente(p_modelo);
  v_custo  := private.maria_calcular_custo(v_in, v_cached, v_out, v_preco);
  -- conta como interação se houve ao menos uma chamada à IA ou se concluiu normalmente
  v_conta  := (p_status = 'concluida') or v_cham > 0;

  update public.maria_interacoes set
      status = p_status,
      operacao = case when p_operacao in ('consulta','acao_preparada','confirmacao') then p_operacao else 'consulta' end,
      chamadas_groq = v_cham, tokens_entrada = v_in, tokens_saida = v_out, tokens_cached = v_cached,
      tokens_total = v_total, custo_usd = v_custo, modelo = left(coalesce(p_modelo, modelo), 120),
      preco_id = v_preco.id, finalizado_em = now(),
      ferramentas = coalesce((select array_agg(left(f, 60)) from unnest(p_ferramentas[1:30]) f), '{}'),
      erro_codigo = left(p_erro_codigo, 60)
   where id = p_interacao_id;

  insert into public.maria_uso_mensal (empresa_id, mes_ref) values (v_emp, i.mes_ref) on conflict do nothing;
  update public.maria_uso_mensal set
      interacoes     = interacoes + case when v_conta then 1 else 0 end,
      chamadas_groq  = chamadas_groq + v_cham,
      tokens_entrada = tokens_entrada + v_in,
      tokens_saida   = tokens_saida + v_out,
      tokens_cached  = tokens_cached + v_cached,
      tokens_total   = tokens_total + v_total,
      custo_usd      = custo_usd + v_custo,
      ultimo_uso     = now(),
      atualizado_em  = now()
   where empresa_id = v_emp and mes_ref = i.mes_ref;

  return jsonb_build_object('ok', true, 'custo_usd', v_custo, 'tokens_total', v_total);
end $function$

CREATE OR REPLACE FUNCTION public.maria_uso_iniciar(p_interacao_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_emp    uuid;
  v_uid    uuid := auth.uid();
  v_cfg    jsonb;
  v_mes    date := private.maria_mes_ref();
  v_uso    public.maria_uso_mensal%rowtype;
  v_glob   public.maria_config_global%rowtype;
  v_preco  public.maria_precos_modelo%rowtype;
  v_res_n  integer; v_res_tok bigint; v_res_custo numeric;
  v_reserva_tok bigint; v_reserva_custo numeric;
  v_lim_i  integer; v_lim_t bigint; v_lim_c numeric;
  v_motivo text;
  v_pend   jsonb;
begin
  perform private.maria_exigir_servidor();
  v_emp := private.exigir_empresa_ativa();
  if p_interacao_id is null then raise exception 'Identificador da interação é obrigatório.'; end if;

  select * into v_glob from public.maria_config_global where id;
  v_cfg := private.maria_config_efetiva(v_emp);
  v_preco := private.maria_preco_vigente(v_glob.modelo_padrao);
  v_reserva_tok := v_glob.reserva_tokens;
  -- reserva de custo: pior caso (tudo cobrado como saída) — conservadora e barata de calcular.
  v_reserva_custo := round(v_reserva_tok * v_preco.usd_milhao_saida / 1000000.0, 8);

  -- Linha do mês + trava (serializa o pré-check da empresa).
  insert into public.maria_uso_mensal (empresa_id, mes_ref) values (v_emp, v_mes) on conflict do nothing;
  select * into v_uso from public.maria_uso_mensal where empresa_id = v_emp and mes_ref = v_mes for update;

  -- Reservas vencidas = a Edge Function não conseguiu finalizar (queda, timeout, JWT expirado no meio).
  -- O consumo real é desconhecido, então são DEBITADAS (1 interação + tokens reservados) em vez de sumirem:
  -- ninguém consegue "uso grátis" interrompendo a requisição. Fica registrado como erro 'reserva_expirada'.
  with exp as (
    update public.maria_interacoes set status = 'erro', erro_codigo = 'reserva_expirada', finalizado_em = now(),
           tokens_total = tokens_reservados
     where empresa_id = v_emp and status = 'reservada'
       and criado_em <= now() - make_interval(secs => v_glob.reserva_ttl_segundos)
    returning mes_ref, tokens_reservados),
  ag as (select mes_ref, count(*) as n, sum(tokens_reservados) as t from exp group by mes_ref)
  update public.maria_uso_mensal u set interacoes = u.interacoes + ag.n, tokens_total = u.tokens_total + ag.t, atualizado_em = now()
    from ag where u.empresa_id = v_emp and u.mes_ref = ag.mes_ref;
  select * into v_uso from public.maria_uso_mensal where empresa_id = v_emp and mes_ref = v_mes;

  if not (v_cfg->>'ativa')::boolean then
    v_motivo := 'desativada';
  else
    select count(*), coalesce(sum(tokens_reservados),0), coalesce(sum(custo_reservado),0)
      into v_res_n, v_res_tok, v_res_custo
      from public.maria_interacoes
     where empresa_id = v_emp and status = 'reservada'
       and criado_em > now() - make_interval(secs => v_glob.reserva_ttl_segundos);

    v_lim_i := nullif(v_cfg->>'limite_interacoes_mes','')::integer;
    v_lim_t := nullif(v_cfg->>'limite_tokens_mes','')::bigint;
    v_lim_c := nullif(v_cfg->>'limite_custo_usd_mes','')::numeric;

    if v_lim_i is not null and v_uso.interacoes + v_res_n >= v_lim_i then v_motivo := 'limite_interacoes';
    elsif v_lim_t is not null and v_uso.tokens_total + v_res_tok >= v_lim_t then v_motivo := 'limite_tokens';
    elsif v_lim_c is not null and v_uso.custo_usd + v_res_custo >= v_lim_c then v_motivo := 'limite_custo';
    end if;
  end if;

  -- Anti-abuso: no máximo 3 consultas simultâneas por usuário (protege a chave compartilhada da Groq).
  if v_motivo is null and (select count(*) from public.maria_interacoes
        where empresa_id = v_emp and user_id = v_uid and status = 'reservada'
          and criado_em > now() - make_interval(secs => v_glob.reserva_ttl_segundos)) >= 3 then
    return jsonb_build_object('permitido', false, 'motivo', 'muitas_simultaneas',
      'mensagem', 'A MARIA está recebendo muitas consultas neste momento. Aguarde alguns segundos e tente novamente.');
  end if;

  if v_motivo is not null then
    insert into public.maria_interacoes (id, empresa_id, user_id, mes_ref, status, operacao, erro_codigo, finalizado_em)
    values (p_interacao_id, v_emp, v_uid, v_mes, 'bloqueada', 'bloqueio', v_motivo, now())
    on conflict (id) do nothing;
    update public.maria_uso_mensal set bloqueios = bloqueios + 1, atualizado_em = now()
     where empresa_id = v_emp and mes_ref = v_mes;
    return jsonb_build_object('permitido', false, 'motivo', v_motivo,
      'mensagem', case when v_motivo = 'desativada'
        then 'A MARIA não está ativa para a sua empresa. Entre em contato com a Florest Sistemas.'
        else 'Seu limite mensal da MARIA foi atingido. Entre em contato com a Florest Sistemas para continuar utilizando o recurso.' end);
  end if;

  insert into public.maria_interacoes (id, empresa_id, user_id, mes_ref, status, tokens_reservados, custo_reservado, modelo)
  values (p_interacao_id, v_emp, v_uid, v_mes, 'reservada', v_reserva_tok, v_reserva_custo, v_glob.modelo_padrao);

  select jsonb_build_object('id', a.id, 'tipo', a.tipo, 'resumo', a.resumo, 'reforcada', a.reforcada, 'expira_em', a.expira_em)
    into v_pend
    from public.maria_acoes_pendentes a
   where a.empresa_id = v_emp and a.user_id = v_uid and a.status = 'pendente' and a.expira_em > now();

  return jsonb_build_object(
    'permitido', true,
    'plano', v_cfg->>'plano',
    'modelo', v_glob.modelo_padrao,
    'consultoria', (v_cfg->>'permite_consultoria')::boolean,
    'acoes', (v_cfg->>'permite_acoes')::boolean,
    'modulos', jsonb_build_object('pet', private.empresa_tem_modulo('pet'), 'bar', private.empresa_tem_modulo('bar')),
    'permissoes', jsonb_build_object(
        'financeiro', private.perm_alguma(array['financeiro','relatorios']),
        'vendas',     private.perm_alguma(array['pdv','dashboard','financeiro','fiscal','relatorios']),
        'clientes',   private.perm_alguma(array['clientes','pdv','dashboard','financeiro','fiscal','relatorios']),
        'produtos',   private.perm_alguma(array['produtos','estoque','notas_entrada','fiscal','dashboard','relatorios','bar_pedidos']),
        'pet',        private.perm_alguma(array['pets','agenda','pacotes']),
        'bar',        private.perm_alguma(array['bar_visualizar','bar_mesas','bar_pedidos','bar_caixa','bar_portaria','bar_configurar'])),
    'acoes_permitidas', private.maria_acoes_permitidas(),
    'acao_pendente', v_pend
  );
end $function$

private.definition:
CREATE OR REPLACE FUNCTION private.maria_acao_bloqueio(p_tipo text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb := private.maria_acao_requisitos(p_tipo);
begin
  if r is null then return 'tipo_invalido'; end if;
  if r ? 'modulo' and not private.empresa_tem_modulo(r->>'modulo') then return 'sem_modulo'; end if;
  if not private.perm_alguma(array(select jsonb_array_elements_text(r->'perms'))) then return 'sem_permissao'; end if;
  if r ? 'extra' and not private.perm_alguma(array(select jsonb_array_elements_text(r->'extra'))) then return 'sem_permissao'; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.maria_acao_executar(p_emp uuid, p_uid uuid, p_acao_id uuid, p_tipo text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bl text; v_id uuid; v_n integer; v_c jsonb; v_u record; v_tot integer;
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_pend integer; v_pr public.produtos%rowtype; v_k text; v_l jsonb;
begin
  v_bl := private.maria_acao_bloqueio(p_tipo);
  if v_bl = 'sem_modulo' then raise exception 'MARIA_SEM_MODULO' using errcode = '42501';
  elsif v_bl is not null then raise exception 'MARIA_SEM_PERMISSAO' using errcode = '42501'; end if;

  if p_tipo = 'cliente_criar' then
    insert into public.clientes (empresa_id, nome, telefone, email, cpf, cep, logradouro, numero, complemento, bairro, cidade, uf)
    values (p_emp, p->>'nome', p->>'telefone', p->>'email', p->>'cpf', p->>'cep', p->>'logradouro', p->>'numero',
            p->>'complemento', p->>'bairro', p->>'cidade', p->>'uf')
    returning id into v_id;
    return jsonb_build_object('mensagem', 'Cliente ' || (p->>'nome') || ' cadastrado com sucesso.', 'registro_id', v_id);

  elsif p_tipo = 'cliente_atualizar' then
    v_c := p->'campos';
    update public.clientes c set
      nome        = case when v_c ? 'nome'        then v_c->>'nome'        else c.nome end,
      telefone    = case when v_c ? 'telefone'    then v_c->>'telefone'    else c.telefone end,
      email       = case when v_c ? 'email'       then v_c->>'email'       else c.email end,
      cep         = case when v_c ? 'cep'         then v_c->>'cep'         else c.cep end,
      logradouro  = case when v_c ? 'logradouro'  then v_c->>'logradouro'  else c.logradouro end,
      numero      = case when v_c ? 'numero'      then v_c->>'numero'      else c.numero end,
      complemento = case when v_c ? 'complemento' then v_c->>'complemento' else c.complemento end,
      bairro      = case when v_c ? 'bairro'      then v_c->>'bairro'      else c.bairro end,
      cidade      = case when v_c ? 'cidade'      then v_c->>'cidade'      else c.cidade end,
      uf          = case when v_c ? 'uf'          then v_c->>'uf'          else c.uf end
     where c.id = (p->>'cliente_id')::uuid and c.empresa_id = p_emp
    returning c.id into v_id;
    if v_id is null then raise exception 'Cliente não encontrado.'; end if;
    return jsonb_build_object('mensagem', 'Cadastro de ' || (p->>'cliente_nome') || ' atualizado.', 'registro_id', v_id);

  elsif p_tipo = 'produto_criar' then
    begin
      insert into public.produtos (empresa_id, codigo, nome, gtin, unidade_comercial, preco_venda, preco_custo, quantidade_estoque, estoque_minimo,
                                   categoria, tipo_fiscal, ncm, cest, cfop, origem_mercadoria, cst_csosn, aliquota_icms, cst_pis, cst_cofins,
                                   codigo_servico, codigo_tributacao_municipal, municipio_incidencia, iss)
      values (p_emp, p->>'codigo', p->>'nome', p->>'gtin', p->>'unidade_comercial', (p->>'preco_venda')::numeric, (p->>'preco_custo')::numeric,
              coalesce((p->>'quantidade_estoque')::numeric, 0), (p->>'estoque_minimo')::numeric,
              p->>'categoria', coalesce(p->>'tipo_fiscal', 'produto'), p->>'ncm', p->>'cest', p->>'cfop', p->>'origem_mercadoria',
              p->>'cst_csosn', (p->>'aliquota_icms')::numeric, p->>'cst_pis', p->>'cst_cofins',
              p->>'codigo_servico', p->>'codigo_tributacao_municipal', p->>'municipio_incidencia', (p->>'iss')::numeric)
      returning id into v_id;
    exception when unique_violation then
      raise exception 'Já existe um produto com esse código ou código de barras.';
    end;
    return jsonb_build_object('mensagem', 'Produto ' || (p->>'nome') || ' cadastrado.'
      || case when coalesce(p->>'tipo_fiscal', 'produto') = 'produto' and (p->>'ncm' is null or p->>'cfop' is null or p->>'cst_csosn' is null)
              then ' Falta completar os dados fiscais (NCM, CFOP e CST/CSOSN) no cadastro de produtos antes de emitir NFC-e.' else '' end,
      'registro_id', v_id);

  elsif p_tipo = 'produto_atualizar_preco' then
    update public.produtos x set
      preco_venda = case when p ? 'preco_venda' then (p->>'preco_venda')::numeric else x.preco_venda end,
      preco_custo = case when p ? 'preco_custo' then (p->>'preco_custo')::numeric else x.preco_custo end
     where x.id = (p->>'produto_id')::uuid and x.empresa_id = p_emp
    returning x.id into v_id;
    if v_id is null then raise exception 'Produto não encontrado.'; end if;
    return jsonb_build_object('mensagem', 'Preço de ' || (p->>'produto_nome') || ' atualizado.', 'registro_id', v_id);

  elsif p_tipo = 'produto_atualizar' then
    v_c := coalesce(p->'campos', '{}'::jsonb); v_l := coalesce(p->'limpar', '[]'::jsonb);
    select * into v_pr from public.produtos where id = (p->>'produto_id')::uuid and empresa_id = p_emp for update;
    if not found then raise exception 'Produto não encontrado.'; end if;
    -- Os campos que serão alterados precisam continuar como estavam quando a alteração foi preparada.
    for v_k in select jsonb_object_keys(coalesce(p->'antes', '{}'::jsonb)) loop
      if (to_jsonb(v_pr)->>v_k) is distinct from (p->'antes'->>v_k) then
        raise exception 'O produto foi alterado por outra pessoa depois que esta alteração foi preparada. Peça novamente para ver os valores atuais.'; end if;
    end loop;
    begin
      update public.produtos x set
        nome                        = case when v_c ? 'nome'                        then v_c->>'nome'                        else x.nome end,
        codigo                      = case when v_c ? 'codigo'                      then v_c->>'codigo'                      else x.codigo end,
        gtin                        = case when v_c ? 'gtin'                        then v_c->>'gtin'                        when v_l ? 'gtin' then null else x.gtin end,
        unidade_comercial           = case when v_c ? 'unidade_comercial'           then v_c->>'unidade_comercial'           when v_l ? 'unidade_comercial' then null else x.unidade_comercial end,
        categoria                   = case when v_c ? 'categoria'                   then v_c->>'categoria'                   when v_l ? 'categoria' then null else x.categoria end,
        preco_venda                 = case when v_c ? 'preco_venda'                 then (v_c->>'preco_venda')::numeric      else x.preco_venda end,
        preco_custo                 = case when v_c ? 'preco_custo'                 then (v_c->>'preco_custo')::numeric      when v_l ? 'preco_custo' then null else x.preco_custo end,
        estoque_minimo              = case when v_c ? 'estoque_minimo'              then (v_c->>'estoque_minimo')::numeric   when v_l ? 'estoque_minimo' then null else x.estoque_minimo end,
        tipo_fiscal                 = case when v_c ? 'tipo_fiscal'                 then v_c->>'tipo_fiscal'                 else x.tipo_fiscal end,
        ncm                         = case when v_c ? 'ncm'                         then v_c->>'ncm'                         when v_l ? 'ncm' then null else x.ncm end,
        cest                        = case when v_c ? 'cest'                        then v_c->>'cest'                        when v_l ? 'cest' then null else x.cest end,
        cfop                        = case when v_c ? 'cfop'                        then v_c->>'cfop'                        when v_l ? 'cfop' then null else x.cfop end,
        origem_mercadoria           = case when v_c ? 'origem_mercadoria'           then v_c->>'origem_mercadoria'           when v_l ? 'origem_mercadoria' then null else x.origem_mercadoria end,
        cst_csosn                   = case when v_c ? 'cst_csosn'                   then v_c->>'cst_csosn'                   when v_l ? 'cst_csosn' then null else x.cst_csosn end,
        aliquota_icms               = case when v_c ? 'aliquota_icms'               then (v_c->>'aliquota_icms')::numeric    when v_l ? 'aliquota_icms' then null else x.aliquota_icms end,
        cst_pis                     = case when v_c ? 'cst_pis'                     then v_c->>'cst_pis'                     when v_l ? 'cst_pis' then null else x.cst_pis end,
        cst_cofins                  = case when v_c ? 'cst_cofins'                  then v_c->>'cst_cofins'                  when v_l ? 'cst_cofins' then null else x.cst_cofins end,
        codigo_servico              = case when v_c ? 'codigo_servico'              then v_c->>'codigo_servico'              when v_l ? 'codigo_servico' then null else x.codigo_servico end,
        codigo_tributacao_municipal = case when v_c ? 'codigo_tributacao_municipal' then v_c->>'codigo_tributacao_municipal' when v_l ? 'codigo_tributacao_municipal' then null else x.codigo_tributacao_municipal end,
        municipio_incidencia        = case when v_c ? 'municipio_incidencia'        then v_c->>'municipio_incidencia'        when v_l ? 'municipio_incidencia' then null else x.municipio_incidencia end,
        iss                         = case when v_c ? 'iss'                         then (v_c->>'iss')::numeric              when v_l ? 'iss' then null else x.iss end
       where x.id = v_pr.id and x.empresa_id = p_emp
      returning x.id into v_id;
    exception when unique_violation then
      raise exception 'Já existe um produto com esse código ou código de barras.';
    end;
    return jsonb_build_object('mensagem', 'Produto ' || (p->>'produto_nome') || ' atualizado.', 'registro_id', v_id);

  elsif p_tipo = 'despesa_criar' then
    insert into public.despesas (empresa_id, descricao, categoria, valor, data, vencimento, status, pago_em, fornecedor_id)
    values (p_emp, p->>'descricao', p->>'categoria', (p->>'valor')::numeric, (p->>'data')::date, (p->>'vencimento')::date,
            p->>'status', case when p->>'status' = 'pago' then v_hoje end, (p->>'fornecedor_id')::uuid)
    returning id into v_id;
    return jsonb_build_object('mensagem', 'Despesa "' || (p->>'descricao') || '" lançada.', 'registro_id', v_id);

  elsif p_tipo = 'despesa_atualizar' then
    v_c := p->'campos';
    update public.despesas d set
      descricao  = case when v_c ? 'descricao'  then v_c->>'descricao'  else d.descricao end,
      valor      = case when v_c ? 'valor'      then (v_c->>'valor')::numeric else d.valor end,
      data       = case when v_c ? 'data'       then (v_c->>'data')::date else d.data end,
      vencimento = case when v_c ? 'vencimento' then (v_c->>'vencimento')::date else d.vencimento end,
      categoria  = case when v_c ? 'categoria'  then v_c->>'categoria'  else d.categoria end
     where d.id = (p->>'despesa_id')::uuid and d.empresa_id = p_emp and d.status <> 'pago'
    returning d.id into v_id;
    if v_id is null then raise exception 'Despesa não encontrada ou já paga.'; end if;
    return jsonb_build_object('mensagem', 'Despesa atualizada.', 'registro_id', v_id);

  elsif p_tipo = 'despesa_marcar_paga' then
    update public.despesas d set status = 'pago', pago_em = (p->>'pago_em')::date
     where d.id = (p->>'despesa_id')::uuid and d.empresa_id = p_emp and d.status <> 'pago'
    returning d.id into v_id;
    if v_id is null then raise exception 'Despesa não encontrada ou já paga.'; end if;
    return jsonb_build_object('mensagem', 'Despesa "' || (p->>'descricao_atual') || '" marcada como paga.', 'registro_id', v_id);

  elsif p_tipo = 'pet_criar' then
    perform 1 from public.clientes where id = (p->>'cliente_id')::uuid and empresa_id = p_emp;
    if not found then raise exception 'Cliente não encontrado.'; end if;
    insert into public.pets (empresa_id, cliente_id, nome, especie, raca, sexo, porte, peso, data_nascimento)
    values (p_emp, (p->>'cliente_id')::uuid, p->>'nome', p->>'especie', p->>'raca', p->>'sexo', p->>'porte',
            (p->>'peso')::numeric, (p->>'data_nascimento')::date)
    returning id into v_id;
    return jsonb_build_object('mensagem', 'Pet ' || (p->>'nome') || ' cadastrado.', 'registro_id', v_id);

  elsif p_tipo = 'agendamento_criar' then
    perform 1 from public.pets where id = (p->>'pet_id')::uuid and empresa_id = p_emp and cliente_id = (p->>'cliente_id')::uuid;
    if not found then raise exception 'Pet não encontrado para esse cliente.'; end if;
    if (p->>'data')::date < v_hoje then raise exception 'A data do agendamento não pode estar no passado.'; end if;
    insert into public.agendamentos (empresa_id, cliente_id, pet_id, servico, data, horario, observacao, status)
    values (p_emp, (p->>'cliente_id')::uuid, (p->>'pet_id')::uuid, p->>'servico', (p->>'data')::date, (p->>'horario')::time,
            p->>'observacao', 'agendado')
    returning id into v_id;
    return jsonb_build_object('mensagem', 'Agendamento de ' || (p->>'servico') || ' para ' || (p->>'pet_nome') || ' em '
             || to_char((p->>'data')::date, 'DD/MM/YYYY') || ' às ' || (p->>'horario') || ' criado.', 'registro_id', v_id);

  elsif p_tipo = 'pacote_criar' then
    select pk.id into v_id from public.criar_pacote_manual(
      (p->>'cliente_id')::uuid, (p->>'pet_id')::uuid, p->>'descricao', (p->>'sessoes_totais')::int,
      (p->>'data_inicio')::date, (p->>'data_validade')::date, p->>'observacoes') pk;
    return jsonb_build_object('mensagem', 'Pacote "' || (p->>'descricao') || '" criado.', 'registro_id', v_id);

  elsif p_tipo = 'pacote_registrar_uso' then
    select * into v_u from public.registrar_uso_pacote((p->>'pacote_id')::uuid, (p->>'agendamento_id')::uuid, p->>'observacao');
    return jsonb_build_object('mensagem', 'Sessão ' || v_u.numero_sessao || ' de ' || v_u.total_sessoes || ' registrada no pacote "' || (p->>'pacote_descricao') || '".',
                              'registro_id', p->>'pacote_id');

  elsif p_tipo = 'pacote_estornar_uso' then
    select * into v_u from public.estornar_uso_pacote((p->>'uso_id')::uuid, p->>'motivo');
    return jsonb_build_object('mensagem', 'Utilização estornada. O pacote agora tem ' || v_u.usadas_sessoes || ' de ' || v_u.total_sessoes || ' sessões usadas.',
                              'registro_id', p->>'uso_id');

  elsif p_tipo = 'bar_abrir_mesa' then
    v_id := public.bar_mesa_abrir((p->>'mesa_id')::uuid, (p->>'pessoas')::int);
    return jsonb_build_object('mensagem', 'Mesa ' || (p->>'mesa_numero') || ' aberta.', 'registro_id', v_id);

  elsif p_tipo = 'bar_adicionar_pessoas' then
    v_tot := public.bar_mesa_adicionar_pessoas((p->>'mesa_id')::uuid, (p->>'quantidade')::int);
    return jsonb_build_object('mensagem', 'Pessoas adicionadas. A mesa ' || (p->>'mesa_numero') || ' agora tem ' || v_tot || ' pessoa(s).');

  elsif p_tipo = 'bar_lancar_pedido' then
    -- idempotência = id da ação pendente (um pedido por confirmação, mesmo com retry)
    select x.pedido_id, x.itens_criados into v_id, v_n
      from public.bar_pedido_lancar((p->>'mesa_id')::uuid,
             (select jsonb_agg(jsonb_build_object('bar_produto_id', e->>'bar_produto_id', 'quantidade', (e->>'quantidade')::numeric,
                                                  'observacao', e->>'observacao'))
                from jsonb_array_elements(p->'itens') e), p_acao_id) x;
    return jsonb_build_object('mensagem', 'Pedido lançado na mesa ' || (p->>'mesa_numero') || ' (' || v_n || ' item(ns)).', 'registro_id', v_id);
  end if;

  raise exception 'Ação não reconhecida.';
end $function$

CREATE OR REPLACE FUNCTION private.maria_acao_normalizar(p_emp uuid, p_tipo text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  r jsonb; n jsonb := '{}'::jsonb; res text := ''; avisos text := '';
  v_id uuid; v_cand jsonb; v_cnt integer;
  c public.clientes%rowtype; pr public.produtos%rowtype; d public.despesas%rowtype; pt public.pets%rowtype;
  pc public.pacotes_clientes%rowtype; ms public.bar_mesas%rowtype;
  s text; num numeric; dt date; hr text; k text;
  v_forn uuid; v_fn text;
  it jsonb; v_itens jsonb := '[]'::jsonb; v_pad text; v_nome_busca text; v_bp record;
  v_campos text[] := '{}';
  o jsonb; v_camp jsonb; v_antes jsonb; v_limp jsonb; v_ant text;
begin
  ---------------------------------------------------------------- clientes
  if p_tipo = 'cliente_criar' then
    s := private.maria_t(p,'nome',120,'nome'); if s is null then return jsonb_build_object('erro','Informe o nome do cliente.'); end if;
    n := jsonb_build_object('nome', s);
    res := 'Cadastrar cliente: ' || s;
    s := private.maria_t(p,'telefone',30,'telefone'); if s is not null then n := n || jsonb_build_object('telefone', s); res := res || E'\nTelefone: ' || s; end if;
    s := private.maria_t(p,'email',120,'e-mail');
    if s is not null then
      if s !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('erro','O e-mail informado é inválido.'); end if;
      n := n || jsonb_build_object('email', lower(s)); res := res || E'\nE-mail: ' || lower(s);
    end if;
    s := private.maria_t(p,'cpf',20,'CPF');
    if s is not null then
      if not private.maria_cpf_valido(s) then return jsonb_build_object('erro','O CPF informado é inválido.'); end if;
      s := regexp_replace(s,'\D','','g');
      if exists (select 1 from public.clientes x where x.empresa_id = p_emp and regexp_replace(coalesce(x.cpf,''),'\D','','g') = s) then
        return jsonb_build_object('erro','Já existe um cliente cadastrado com esse CPF.'); end if;
      n := n || jsonb_build_object('cpf', s); res := res || E'\nCPF: ' || s;
    end if;
    foreach k in array array['cep','logradouro','numero','complemento','bairro','cidade','uf'] loop
      s := private.maria_t(p,k,case k when 'logradouro' then 120 when 'cidade' then 80 when 'bairro' then 80 when 'complemento' then 80 else 20 end,k);
      if s is not null then
        if k = 'uf' then s := upper(s); if s !~ '^[A-Z]{2}$' then return jsonb_build_object('erro','A UF deve ter 2 letras.'); end if; end if;
        if k = 'cep' then s := regexp_replace(s,'\D','','g'); if length(s) <> 8 then return jsonb_build_object('erro','O CEP deve ter 8 dígitos.'); end if; end if;
        n := n || jsonb_build_object(k, s);
      end if;
    end loop;
    if n ? 'cidade' then res := res || E'\nCidade: ' || (n->>'cidade') || coalesce('/' || (n->>'uf'), ''); end if;
    if exists (select 1 from public.clientes x where x.empresa_id = p_emp and private.maria_norm(btrim(x.nome)) = private.maria_norm(n->>'nome')) then
      avisos := E'\nAtenção: já existe um cliente com esse mesmo nome.'; end if;
    return jsonb_build_object('params', n, 'resumo', res || avisos);

  elsif p_tipo = 'cliente_atualizar' then
    select o_id, o_candidatos into v_id, v_cand from private.maria_resolver_cliente(p_emp, private.maria_u(p,'cliente_id','cliente'), private.maria_t(p,'cliente',120,'cliente'));
    if v_cand is not null then return jsonb_build_object('ambiguo', true, 'campo', 'cliente', 'candidatos', v_cand); end if;
    if v_id is null then return jsonb_build_object('erro','Cliente não encontrado.'); end if;
    select * into c from public.clientes where id = v_id and empresa_id = p_emp;
    n := jsonb_build_object('cliente_id', c.id, 'cliente_nome', c.nome);
    res := 'Atualizar o cadastro do cliente ' || c.nome || ':';
    foreach k in array array['nome','telefone','email','cep','logradouro','numero','complemento','bairro','cidade','uf'] loop
      if p ? k then
        s := private.maria_t(p, k, case k when 'nome' then 120 when 'email' then 120 when 'logradouro' then 120 when 'cidade' then 80 when 'bairro' then 80 when 'complemento' then 80 when 'telefone' then 30 else 20 end, k);
        if k = 'nome' and s is null then return jsonb_build_object('erro','O nome do cliente não pode ficar vazio.'); end if;
        if k = 'email' and s is not null then
          if s !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('erro','O e-mail informado é inválido.'); end if; s := lower(s); end if;
        if k = 'uf' and s is not null then s := upper(s); if s !~ '^[A-Z]{2}$' then return jsonb_build_object('erro','A UF deve ter 2 letras.'); end if; end if;
        if k = 'cep' and s is not null then s := regexp_replace(s,'\D','','g'); if length(s) <> 8 then return jsonb_build_object('erro','O CEP deve ter 8 dígitos.'); end if; end if;
        n := n || jsonb_build_object('campos', coalesce(n->'campos','{}'::jsonb) || jsonb_build_object(k, s));
        res := res || E'\n- ' || k || ': ' || coalesce((to_jsonb(c)->>k), '(vazio)') || ' → ' || coalesce(s, '(vazio)');
      end if;
    end loop;
    if not (n ? 'campos') then return jsonb_build_object('erro','Informe pelo menos um campo para alterar.'); end if;
    return jsonb_build_object('params', n, 'resumo', res);

  ---------------------------------------------------------------- produtos
  elsif p_tipo = 'produto_criar' then
    o := private.maria_prod_campos(p_emp, p, null);
    if not (o ? 'nome') then return jsonb_build_object('erro','Informe o nome do produto.'); end if;
    if not (o ? 'preco_venda') then return jsonb_build_object('erro','Informe o preço de venda do produto.'); end if;
    n := o;
    num := private.maria_n(p,'quantidade_estoque',0,10000000,'quantidade em estoque');
    if num is not null then n := n || jsonb_build_object('quantidade_estoque', round(num,4)); end if;
    res := 'Cadastrar produto: ' || (o->>'nome');
    foreach k in array private.maria_prod_ordem() loop
      if k <> 'nome' and o ? k then res := res || E'\n' || private.maria_prod_rotulo(k) || ': ' || private.maria_prod_fmt(k, o->>k); end if;
    end loop;
    if n ? 'quantidade_estoque' then res := res || E'\nEstoque inicial: ' || private.maria_prod_fmt('estoque_minimo', n->>'quantidade_estoque'); end if;
    if o ? 'unidade_comercial' and not private.maria_unidade_padrao(o->>'unidade_comercial') then
      res := res || E'\nAtenção: a unidade ' || (o->>'unidade_comercial') || ' não está na lista padrão do cadastro de produtos; será gravada como informada.'; end if;
    if coalesce(o->>'tipo_fiscal', 'produto') = 'produto' then
      v_campos := '{}';
      if not (o ? 'ncm') then v_campos := array_append(v_campos, 'NCM'); end if;
      if not (o ? 'cfop') then v_campos := array_append(v_campos, 'CFOP'); end if;
      if not (o ? 'cst_csosn') then v_campos := array_append(v_campos, 'CST/CSOSN'); end if;
      if array_length(v_campos, 1) > 0 then
        res := res || E'\nNão informados (ficam vazios; a MARIA não inventa dados fiscais): ' || array_to_string(v_campos, ', ')
                   || E'. Complete no cadastro de produtos antes de emitir NFC-e.'; end if;
    end if;
    if exists (select 1 from public.produtos x where x.empresa_id = p_emp and private.maria_norm(btrim(x.nome)) = private.maria_norm(o->>'nome')) then
      res := res || E'\nAtenção: já existe um produto com esse mesmo nome.'; end if;
    return jsonb_build_object('params', n, 'resumo', res);

  elsif p_tipo = 'produto_atualizar_preco' then
    select o_id, o_candidatos into v_id, v_cand from private.maria_resolver_produto(p_emp, private.maria_u(p,'produto_id','produto'), private.maria_t(p,'produto',120,'produto'));
    if v_cand is not null then return jsonb_build_object('ambiguo', true, 'campo', 'produto', 'candidatos', v_cand); end if;
    if v_id is null then return jsonb_build_object('erro','Produto não encontrado.'); end if;
    select * into pr from public.produtos where id = v_id and empresa_id = p_emp;
    n := jsonb_build_object('produto_id', pr.id, 'produto_nome', pr.nome);
    res := 'Alterar preço do produto ' || pr.nome || ':';
    num := private.maria_n(p,'preco_venda',0,9999999.99,'preço de venda');
    if num is not null then
      if round(num,2) = pr.preco_venda then return jsonb_build_object('erro','O preço de venda informado é igual ao atual.'); end if;
      n := n || jsonb_build_object('preco_venda', round(num,2));
      res := res || E'\nPreço de venda: ' || private.maria_brl(pr.preco_venda) || ' → ' || private.maria_brl(num);
      if pr.preco_venda > 0 and abs(num - pr.preco_venda) / pr.preco_venda > 0.5 then res := res || E'\nAtenção: variação de mais de 50% no preço.'; end if;
      if num = 0 then res := res || E'\nAtenção: o preço será zerado.'; end if;
    end if;
    num := private.maria_n(p,'preco_custo',0,9999999.99,'preço de custo');
    if num is not null then
      n := n || jsonb_build_object('preco_custo', round(num,4));
      res := res || E'\nPreço de custo: ' || coalesce(private.maria_brl(pr.preco_custo), '(não informado)') || ' → ' || private.maria_brl(num);
    end if;
    if not (n ? 'preco_venda' or n ? 'preco_custo') then return jsonb_build_object('erro','Informe o novo preço de venda e/ou de custo.'); end if;
    return jsonb_build_object('params', n, 'resumo', res);

  elsif p_tipo = 'produto_atualizar' then
    -- Campos que a MARIA nunca altera por aqui (empresa/identificadores/auditoria/pacote) e o estoque (sem operação oficial segura).
    foreach k in array array['empresa_id','id','criado_em','atualizado_em','vendavel_pacote','pacote_qtd','pacote_preco'] loop
      if p ? k and jsonb_typeof(p->k) <> 'null' then return jsonb_build_object('erro','Esse campo não pode ser alterado pela MARIA.'); end if;
    end loop;
    if p ? 'quantidade_estoque' and jsonb_typeof(p->'quantidade_estoque') <> 'null' and btrim(p->>'quantidade_estoque') <> '' then
      return jsonb_build_object('erro','A MARIA não altera a quantidade em estoque. Use a tela Estoque (Ajustar), uma Nota Fiscal de Entrada ou as vendas.'); end if;
    select o_id, o_candidatos into v_id, v_cand from private.maria_resolver_produto(p_emp, private.maria_u(p,'produto_id','produto'), private.maria_t(p,'produto',120,'produto'));
    if v_cand is not null then return jsonb_build_object('ambiguo', true, 'campo', 'produto', 'candidatos', v_cand); end if;
    if v_id is null then return jsonb_build_object('erro','Produto não encontrado.'); end if;
    select * into pr from public.produtos where id = v_id and empresa_id = p_emp;
    o := private.maria_prod_campos(p_emp, p, v_id);
    -- limpar: lista de campos opcionais a esvaziar (só quando o usuário pedir explicitamente)
    v_limp := '[]'::jsonb;
    if p ? 'limpar' and jsonb_typeof(p->'limpar') not in ('null') then
      if jsonb_typeof(p->'limpar') <> 'array' then return jsonb_build_object('erro','Os campos a limpar foram informados de forma inválida.'); end if;
      for k in select jsonb_array_elements_text(p->'limpar') loop
        if not (k = any (array['gtin','unidade_comercial','categoria','preco_custo','estoque_minimo','ncm','cest','cfop','origem_mercadoria',
                               'cst_csosn','aliquota_icms','cst_pis','cst_cofins','codigo_servico','codigo_tributacao_municipal',
                               'municipio_incidencia','iss'])) then
          return jsonb_build_object('erro','O campo "' || left(k, 40) || '" não pode ser esvaziado pela MARIA.'); end if;
        if o ? k then return jsonb_build_object('erro','O campo ' || private.maria_prod_rotulo(k) || ' foi informado para alterar e para esvaziar ao mesmo tempo.'); end if;
        if not (v_limp ? k) and (to_jsonb(pr)->>k) is not null then v_limp := v_limp || to_jsonb(k); end if;
      end loop;
    end if;
    -- Só entram as diferenças reais (valores iguais aos atuais são descartados).
    v_camp := '{}'::jsonb; v_antes := '{}'::jsonb;
    foreach k in array private.maria_prod_ordem() loop
      if o ? k then
        v_ant := to_jsonb(pr)->>k;
        if k in ('preco_venda','preco_custo','estoque_minimo','aliquota_icms','iss') then
          if v_ant is not null and v_ant::numeric = (o->>k)::numeric then continue; end if;
        elsif v_ant is not distinct from (o->>k) then continue; end if;
        v_camp := v_camp || jsonb_build_object(k, o->k);
        v_antes := v_antes || jsonb_build_object(k, v_ant);
      elsif v_limp ? k then
        v_antes := v_antes || jsonb_build_object(k, to_jsonb(pr)->>k);
      end if;
    end loop;
    if v_camp = '{}'::jsonb and v_limp = '[]'::jsonb then
      return jsonb_build_object('erro','Os valores informados são iguais aos que o produto já tem. Nada a alterar.'); end if;
    n := jsonb_build_object('produto_id', pr.id, 'produto_nome', pr.nome, 'campos', v_camp, 'limpar', v_limp, 'antes', v_antes);
    res := 'Alterar o produto ' || pr.nome || ':';
    foreach k in array private.maria_prod_ordem() loop
      if v_camp ? k then
        res := res || E'\n' || private.maria_prod_rotulo(k) || ': ' || private.maria_prod_fmt(k, v_antes->>k) || ' → ' || private.maria_prod_fmt(k, v_camp->>k);
      elsif v_limp ? k then
        res := res || E'\n' || private.maria_prod_rotulo(k) || ': ' || private.maria_prod_fmt(k, v_antes->>k) || ' → (vazio)';
      end if;
    end loop;
    if v_camp ? 'preco_venda' then
      num := (v_camp->>'preco_venda')::numeric;
      if pr.preco_venda > 0 and abs(num - pr.preco_venda) / pr.preco_venda > 0.5 then res := res || E'\nAtenção: variação de mais de 50% no preço.'; end if;
      if num = 0 then res := res || E'\nAtenção: o preço será zerado.'; end if;
    end if;
    if v_camp ? 'codigo' then res := res || E'\nAtenção: o código interno é gerado automaticamente pelo sistema; confirme que deseja trocá-lo manualmente.'; end if;
    if v_camp ? 'unidade_comercial' and not private.maria_unidade_padrao(v_camp->>'unidade_comercial') then
      res := res || E'\nAtenção: a unidade ' || (v_camp->>'unidade_comercial') || ' não está na lista padrão do cadastro de produtos; será gravada como informada.'; end if;
    return jsonb_build_object('params', n, 'resumo', res);

  ---------------------------------------------------------------- despesas
  elsif p_tipo = 'despesa_criar' then
    s := private.maria_t(p,'descricao',200,'descrição'); if s is null then return jsonb_build_object('erro','Informe a descrição da despesa.'); end if;
    n := jsonb_build_object('descricao', s);
    num := private.maria_n(p,'valor',0.01,9999999.99,'valor');
    if num is null then return jsonb_build_object('erro','Informe o valor da despesa.'); end if;
    n := n || jsonb_build_object('valor', round(num,2));
    dt := coalesce(private.maria_d(p,'data','despesa'), v_hoje);
    if dt > v_hoje + 366 or dt < v_hoje - 1830 then return jsonb_build_object('erro','A data da despesa está fora do intervalo permitido.'); end if;
    n := n || jsonb_build_object('data', dt);
    res := 'Lançar despesa: ' || s || E'\nValor: ' || private.maria_brl(num) || E'\nData: ' || private.maria_dtbr(dt);
    dt := private.maria_d(p,'vencimento','vencimento');
    if dt is not null then
      if dt > v_hoje + 1830 or dt < v_hoje - 1830 then return jsonb_build_object('erro','O vencimento está fora do intervalo permitido.'); end if;
      n := n || jsonb_build_object('vencimento', dt); res := res || E'\nVencimento: ' || private.maria_dtbr(dt);
    end if;
    s := private.maria_t(p,'categoria',80,'categoria'); if s is not null then n := n || jsonb_build_object('categoria', s); res := res || E'\nCategoria: ' || s; end if;
    s := lower(coalesce(private.maria_t(p,'status',20,'situação'), 'pendente'));
    if s not in ('pendente','pago') then return jsonb_build_object('erro','A situação deve ser pendente ou pago.'); end if;
    n := n || jsonb_build_object('status', s); res := res || E'\nSituação: ' || s;
    v_fn := private.maria_t(p,'fornecedor',120,'fornecedor');
    if v_fn is not null then
      v_pad := private.maria_like(v_fn);
      select count(*) into v_cnt from public.fornecedores f where f.empresa_id = p_emp and
         (private.maria_norm(coalesce(f.nome_fantasia,'')) like v_pad escape '\' or private.maria_norm(f.razao_social) like v_pad escape '\');
      if v_cnt = 0 then return jsonb_build_object('erro','Fornecedor não encontrado. Cadastre o fornecedor primeiro (a MARIA não cadastra fornecedores).'); end if;
      if v_cnt > 1 then
        select jsonb_agg(jsonb_build_object('id', f.id, 'nome', coalesce(f.nome_fantasia, f.razao_social))) into v_cand from (
          select * from public.fornecedores f2 where f2.empresa_id = p_emp and (private.maria_norm(coalesce(f2.nome_fantasia,'')) like v_pad escape '\'
             or private.maria_norm(f2.razao_social) like v_pad escape '\') order by f2.razao_social limit 8) f;
        return jsonb_build_object('ambiguo', true, 'campo', 'fornecedor', 'candidatos', v_cand);
      end if;
      select f.id, coalesce(f.nome_fantasia, f.razao_social) into v_forn, v_fn from public.fornecedores f where f.empresa_id = p_emp and
         (private.maria_norm(coalesce(f.nome_fantasia,'')) like v_pad escape '\' or private.maria_norm(f.razao_social) like v_pad escape '\');
      n := n || jsonb_build_object('fornecedor_id', v_forn, 'fornecedor_nome', v_fn); res := res || E'\nFornecedor: ' || v_fn;
    end if;
    return jsonb_build_object('params', n, 'resumo', res);

  elsif p_tipo in ('despesa_atualizar','despesa_marcar_paga') then
    v_id := private.maria_u(p,'despesa_id','despesa');
    if v_id is null then return jsonb_build_object('erro','Informe qual despesa (consulte as despesas primeiro para identificá-la).'); end if;
    select * into d from public.despesas where id = v_id and empresa_id = p_emp;
    if not found then return jsonb_build_object('erro','Despesa não encontrada.'); end if;
    n := jsonb_build_object('despesa_id', d.id, 'descricao_atual', d.descricao);
    if p_tipo = 'despesa_marcar_paga' then
      if d.status = 'pago' then return jsonb_build_object('erro','Essa despesa já está marcada como paga.'); end if;
      dt := coalesce(private.maria_d(p,'pago_em','pagamento'), v_hoje);
      if dt > v_hoje then return jsonb_build_object('erro','A data de pagamento não pode ser futura.'); end if;
      n := n || jsonb_build_object('pago_em', dt);
      return jsonb_build_object('params', n, 'resumo', 'Marcar como PAGA a despesa "' || d.descricao || '" de ' || private.maria_brl(d.valor)
                                 || E'\nData do pagamento: ' || private.maria_dtbr(dt));
    end if;
    if d.status = 'pago' then return jsonb_build_object('erro','Despesa já paga não pode ser alterada pela MARIA.'); end if;
    if d.nota_entrada_id is not null and (p ? 'valor' or p ? 'descricao' or p ? 'data') then
      return jsonb_build_object('erro','Despesas geradas por nota de entrada devem ser alteradas pela própria nota (apenas vencimento e categoria podem ser ajustados aqui).'); end if;
    res := 'Alterar a despesa "' || d.descricao || '":';
    if p ? 'descricao' then s := private.maria_t(p,'descricao',200,'descrição'); if s is null then return jsonb_build_object('erro','A descrição não pode ficar vazia.'); end if;
      n := n || jsonb_build_object('campos', coalesce(n->'campos','{}'::jsonb) || jsonb_build_object('descricao', s)); res := res || E'\nDescrição: ' || d.descricao || ' → ' || s; end if;
    if p ? 'valor' then num := private.maria_n(p,'valor',0.01,9999999.99,'valor'); if num is null then return jsonb_build_object('erro','O valor não pode ficar vazio.'); end if;
      n := n || jsonb_build_object('campos', coalesce(n->'campos','{}'::jsonb) || jsonb_build_object('valor', round(num,2))); res := res || E'\nValor: ' || private.maria_brl(d.valor) || ' → ' || private.maria_brl(num); end if;
    if p ? 'data' then dt := private.maria_d(p,'data','despesa'); if dt is null then return jsonb_build_object('erro','A data não pode ficar vazia.'); end if;
      n := n || jsonb_build_object('campos', coalesce(n->'campos','{}'::jsonb) || jsonb_build_object('data', dt)); res := res || E'\nData: ' || private.maria_dtbr(d.data) || ' → ' || private.maria_dtbr(dt); end if;
    if p ? 'vencimento' then dt := private.maria_d(p,'vencimento','vencimento');
      n := n || jsonb_build_object('campos', coalesce(n->'campos','{}'::jsonb) || jsonb_build_object('vencimento', dt)); res := res || E'\nVencimento: ' || coalesce(private.maria_dtbr(d.vencimento),'(vazio)') || ' → ' || coalesce(private.maria_dtbr(dt),'(vazio)'); end if;
    if p ? 'categoria' then s := private.maria_t(p,'categoria',80,'categoria');
      n := n || jsonb_build_object('campos', coalesce(n->'campos','{}'::jsonb) || jsonb_build_object('categoria', s)); res := res || E'\nCategoria: ' || coalesce(d.categoria,'(vazio)') || ' → ' || coalesce(s,'(vazio)'); end if;
    if not (n ? 'campos') then return jsonb_build_object('erro','Informe pelo menos um campo para alterar.'); end if;
    return jsonb_build_object('params', n, 'resumo', res);

  ---------------------------------------------------------------- PET
  elsif p_tipo in ('pet_criar','agendamento_criar','pacote_criar') then
    select o_id, o_candidatos into v_id, v_cand from private.maria_resolver_cliente(p_emp, private.maria_u(p,'cliente_id','cliente'), private.maria_t(p,'cliente',120,'cliente'));
    if v_cand is not null then return jsonb_build_object('ambiguo', true, 'campo', 'cliente', 'candidatos', v_cand); end if;
    if v_id is null then return jsonb_build_object('erro','Cliente (tutor) não encontrado.'); end if;
    select * into c from public.clientes where id = v_id and empresa_id = p_emp;
    n := jsonb_build_object('cliente_id', c.id, 'cliente_nome', c.nome);

    if p_tipo = 'pet_criar' then
      s := private.maria_t(p,'nome',80,'nome do pet'); if s is null then return jsonb_build_object('erro','Informe o nome do pet.'); end if;
      if exists (select 1 from public.pets x where x.empresa_id = p_emp and x.cliente_id = c.id and private.maria_norm(btrim(x.nome)) = private.maria_norm(s) and x.ativo) then
        return jsonb_build_object('erro','Esse cliente já tem um pet com esse nome.'); end if;
      n := n || jsonb_build_object('nome', s);
      res := 'Cadastrar pet ' || s || ' (tutor: ' || c.nome || ')';
      foreach k in array array['especie','raca','sexo','porte'] loop
        s := private.maria_t(p,k,60,k); if s is not null then n := n || jsonb_build_object(k, s); res := res || E'\n' || initcap(k) || ': ' || s; end if;
      end loop;
      num := private.maria_n(p,'peso',0.01,500,'peso'); if num is not null then n := n || jsonb_build_object('peso', num); res := res || E'\nPeso: ' || num || ' kg'; end if;
      dt := private.maria_d(p,'data_nascimento','nascimento');
      if dt is not null then if dt > v_hoje then return jsonb_build_object('erro','A data de nascimento não pode ser futura.'); end if;
        n := n || jsonb_build_object('data_nascimento', dt); res := res || E'\nNascimento: ' || private.maria_dtbr(dt); end if;
      return jsonb_build_object('params', n, 'resumo', res);
    end if;

    -- escolher o pet do cliente (agendamento e pacote)
    select count(*) into v_cnt from public.pets x where x.empresa_id = p_emp and x.cliente_id = c.id and x.ativo;
    s := private.maria_t(p,'pet',80,'pet');
    if private.maria_u(p,'pet_id','pet') is not null then
      select * into pt from public.pets where id = private.maria_u(p,'pet_id','pet') and empresa_id = p_emp and cliente_id = c.id;
    elsif s is not null then
      select count(*) into v_cnt from public.pets x where x.empresa_id = p_emp and x.cliente_id = c.id and x.ativo and private.maria_norm(x.nome) like private.maria_like(s) escape '\';
      if v_cnt > 1 then
        select jsonb_agg(jsonb_build_object('id', x.id, 'nome', x.nome, 'especie', x.especie)) into v_cand from public.pets x
         where x.empresa_id = p_emp and x.cliente_id = c.id and x.ativo and private.maria_norm(x.nome) like private.maria_like(s) escape '\';
        return jsonb_build_object('ambiguo', true, 'campo', 'pet', 'candidatos', v_cand);
      end if;
      select * into pt from public.pets x where x.empresa_id = p_emp and x.cliente_id = c.id and x.ativo and private.maria_norm(x.nome) like private.maria_like(s) escape '\';
    elsif v_cnt = 1 then
      select * into pt from public.pets x where x.empresa_id = p_emp and x.cliente_id = c.id and x.ativo;
    elsif v_cnt > 1 then
      select jsonb_agg(jsonb_build_object('id', x.id, 'nome', x.nome, 'especie', x.especie)) into v_cand from public.pets x where x.empresa_id = p_emp and x.cliente_id = c.id and x.ativo;
      return jsonb_build_object('ambiguo', true, 'campo', 'pet', 'candidatos', v_cand);
    end if;
    if pt.id is null then return jsonb_build_object('erro','Pet não encontrado para esse cliente.'); end if;
    n := n || jsonb_build_object('pet_id', pt.id, 'pet_nome', pt.nome);

    if p_tipo = 'agendamento_criar' then
      s := private.maria_t(p,'servico',100,'serviço'); if s is null then return jsonb_build_object('erro','Informe o serviço do agendamento.'); end if;
      dt := private.maria_d(p,'data','agendamento'); if dt is null then return jsonb_build_object('erro','Informe a data do agendamento.'); end if;
      if dt < v_hoje then return jsonb_build_object('erro','A data do agendamento não pode estar no passado.'); end if;
      if dt > v_hoje + 366 then return jsonb_build_object('erro','A data do agendamento está distante demais (máximo 1 ano).'); end if;
      hr := private.maria_t(p,'horario',8,'horário'); if hr is null then return jsonb_build_object('erro','Informe o horário do agendamento.'); end if;
      hr := regexp_replace(hr, '^(\d{1,2})h(\d{2})?$', '\1:\2'); hr := regexp_replace(hr, ':$', ':00');
      if hr !~ '^([01]?\d|2[0-3]):[0-5]\d$' then return jsonb_build_object('erro','O horário informado é inválido (use HH:MM).'); end if;
      hr := lpad(split_part(hr,':',1),2,'0') || ':' || split_part(hr,':',2);
      n := n || jsonb_build_object('servico', s, 'data', dt, 'horario', hr);
      res := 'Agendar ' || s || ' para ' || pt.nome || ' (tutor: ' || c.nome || E')\nData: ' || private.maria_dtbr(dt) || ' às ' || hr;
      s := private.maria_t(p,'observacao',300,'observação'); if s is not null then n := n || jsonb_build_object('observacao', s); res := res || E'\nObservação: ' || s; end if;
      if exists (select 1 from public.agendamentos a where a.empresa_id = p_emp and a.data = dt and a.horario = hr::time and a.status = 'agendado') then
        res := res || E'\nAtenção: já existe outro agendamento nesse mesmo dia e horário.'; end if;
      return jsonb_build_object('params', n, 'resumo', res);
    end if;

    -- pacote_criar
    s := private.maria_t(p,'descricao',120,'descrição do pacote'); if s is null then return jsonb_build_object('erro','Informe a descrição do pacote.'); end if;
    num := private.maria_n(p,'sessoes_totais',1,200,'quantidade de sessões'); if num is null or num <> trunc(num) then return jsonb_build_object('erro','Informe a quantidade de sessões (número inteiro).'); end if;
    n := n || jsonb_build_object('descricao', s, 'sessoes_totais', num::int);
    dt := coalesce(private.maria_d(p,'data_inicio','início'), v_hoje); n := n || jsonb_build_object('data_inicio', dt);
    res := 'Criar pacote "' || s || '" de ' || num::int || ' sessões para ' || pt.nome || ' (tutor: ' || c.nome || E')\nInício: ' || private.maria_dtbr(dt);
    dt := private.maria_d(p,'data_validade','validade');
    if dt is not null then
      if dt < (n->>'data_inicio')::date then return jsonb_build_object('erro','A validade não pode ser anterior ao início.'); end if;
      n := n || jsonb_build_object('data_validade', dt); res := res || E'\nValidade: ' || private.maria_dtbr(dt);
    end if;
    s := private.maria_t(p,'observacoes',300,'observações'); if s is not null then n := n || jsonb_build_object('observacoes', s); end if;
    return jsonb_build_object('params', n, 'resumo', res);

  elsif p_tipo = 'pacote_registrar_uso' then
    v_id := private.maria_u(p,'pacote_id','pacote');
    if v_id is null then
      select o_id, o_candidatos into v_id, v_cand from private.maria_resolver_cliente(p_emp, private.maria_u(p,'cliente_id','cliente'), private.maria_t(p,'cliente',120,'cliente'));
      if v_cand is not null then return jsonb_build_object('ambiguo', true, 'campo', 'cliente', 'candidatos', v_cand); end if;
      if v_id is null then return jsonb_build_object('erro','Informe o pacote (ou o cliente dono do pacote).'); end if;
      select count(*) into v_cnt from public.pacotes_clientes x where x.empresa_id = p_emp and x.cliente_id = v_id and x.sessoes_usadas < x.sessoes_totais
         and (x.data_validade is null or x.data_validade >= v_hoje);
      if v_cnt = 0 then return jsonb_build_object('erro','Esse cliente não tem pacote ativo com sessões disponíveis.'); end if;
      if v_cnt > 1 then
        select jsonb_agg(jsonb_build_object('pacote_id', x.id, 'descricao', x.descricao, 'restantes', x.sessoes_totais - x.sessoes_usadas)) into v_cand
          from public.pacotes_clientes x where x.empresa_id = p_emp and x.cliente_id = v_id and x.sessoes_usadas < x.sessoes_totais and (x.data_validade is null or x.data_validade >= v_hoje);
        return jsonb_build_object('ambiguo', true, 'campo', 'pacote', 'candidatos', v_cand);
      end if;
      select x.id into v_id from public.pacotes_clientes x where x.empresa_id = p_emp and x.cliente_id = v_id and x.sessoes_usadas < x.sessoes_totais and (x.data_validade is null or x.data_validade >= v_hoje);
    end if;
    select * into pc from public.pacotes_clientes where id = v_id and empresa_id = p_emp;
    if not found then return jsonb_build_object('erro','Pacote não encontrado.'); end if;
    if pc.sessoes_usadas >= pc.sessoes_totais then return jsonb_build_object('erro','Esse pacote já está concluído.'); end if;
    if pc.data_validade is not null and pc.data_validade < v_hoje then return jsonb_build_object('erro','Esse pacote está vencido.'); end if;
    n := jsonb_build_object('pacote_id', pc.id, 'pacote_descricao', pc.descricao);
    v_id := private.maria_u(p,'agendamento_id','agendamento'); if v_id is not null then n := n || jsonb_build_object('agendamento_id', v_id); end if;
    s := private.maria_t(p,'observacao',300,'observação'); if s is not null then n := n || jsonb_build_object('observacao', s); end if;
    return jsonb_build_object('params', n, 'resumo', 'Registrar o uso de 1 sessão do pacote "' || pc.descricao || '" (sessão ' || (pc.sessoes_usadas + 1) || ' de ' || pc.sessoes_totais || ')');

  elsif p_tipo = 'pacote_estornar_uso' then
    v_id := private.maria_u(p,'uso_id','uso');
    if v_id is null then return jsonb_build_object('erro','Informe qual utilização estornar (consulte os pacotes para identificar).'); end if;
    s := private.maria_t(p,'motivo',200,'motivo'); if s is null or length(s) < 3 then return jsonb_build_object('erro','Informe o motivo do estorno.'); end if;
    if not exists (select 1 from public.pacote_usos u where u.id = v_id and u.empresa_id = p_emp and not u.estornado) then
      return jsonb_build_object('erro','Utilização não encontrada ou já estornada.'); end if;
    select pk.descricao, u.numero_sessao into s, num from public.pacote_usos u join public.pacotes_clientes pk on pk.id = u.pacote_id and pk.empresa_id = u.empresa_id
     where u.id = v_id and u.empresa_id = p_emp;
    n := jsonb_build_object('uso_id', v_id, 'motivo', private.maria_t(p,'motivo',200,'motivo'));
    return jsonb_build_object('params', n, 'reforcada', true,
      'resumo', 'ESTORNAR a sessão ' || coalesce(num::text,'?') || ' do pacote "' || s || '" (a sessão volta a ficar disponível).' || E'\nMotivo: ' || (n->>'motivo'));

  ---------------------------------------------------------------- BAR
  elsif p_tipo in ('bar_abrir_mesa','bar_adicionar_pessoas','bar_lancar_pedido') then
    num := private.maria_n(p,'mesa_numero',1,9999,'número da mesa'); if num is null or num <> trunc(num) then return jsonb_build_object('erro','Informe o número da mesa.'); end if;
    select * into ms from public.bar_mesas where empresa_id = p_emp and numero = num::int;
    if not found then return jsonb_build_object('erro','Mesa ' || num::int || ' não encontrada.'); end if;
    if ms.status = 'fechada' then return jsonb_build_object('erro','A mesa ' || ms.numero || ' está fora de serviço.'); end if;
    n := jsonb_build_object('mesa_id', ms.id, 'mesa_numero', ms.numero);

    if p_tipo = 'bar_abrir_mesa' then
      if ms.status <> 'livre' then return jsonb_build_object('erro','A mesa ' || ms.numero || ' já está ocupada.'); end if;
      num := coalesce(private.maria_n(p,'pessoas',0,200,'quantidade de pessoas'), 0); n := n || jsonb_build_object('pessoas', num::int);
      return jsonb_build_object('params', n, 'resumo', 'Abrir a mesa ' || ms.numero || ' com ' || num::int || ' pessoa(s)');
    elsif p_tipo = 'bar_adicionar_pessoas' then
      if ms.status <> 'ocupada' then return jsonb_build_object('erro','A mesa ' || ms.numero || ' não está ocupada.'); end if;
      num := private.maria_n(p,'quantidade',1,200,'quantidade de pessoas'); if num is null or num <> trunc(num) then return jsonb_build_object('erro','Informe quantas pessoas adicionar.'); end if;
      n := n || jsonb_build_object('quantidade', num::int);
      return jsonb_build_object('params', n, 'resumo', 'Adicionar ' || num::int || ' pessoa(s) na mesa ' || ms.numero || ' (hoje: ' || ms.pessoas_atual || ')');
    end if;

    -- bar_lancar_pedido
    if p->'itens' is null or jsonb_typeof(p->'itens') <> 'array' or jsonb_array_length(p->'itens') = 0 then return jsonb_build_object('erro','Informe os itens do pedido.'); end if;
    if jsonb_array_length(p->'itens') > 20 then return jsonb_build_object('erro','No máximo 20 itens por pedido pela MARIA.'); end if;
    res := 'Lançar pedido na mesa ' || ms.numero || case when ms.status = 'livre' then ' (a mesa será aberta)' else '' end || ':';
    for it in select * from jsonb_array_elements(p->'itens') loop
      if jsonb_typeof(it) <> 'object' then return jsonb_build_object('erro','Item do pedido inválido.'); end if;
      v_nome_busca := private.maria_t(it,'produto',120,'produto'); if v_nome_busca is null then return jsonb_build_object('erro','Informe o nome do produto de cada item.'); end if;
      num := private.maria_n(it,'quantidade',0.001,500,'quantidade'); if num is null then return jsonb_build_object('erro','Informe a quantidade de cada item.'); end if;
      v_pad := private.maria_like(v_nome_busca);
      select count(*) into v_cnt from public.bar_produtos bp join public.produtos x on x.id = bp.produto_id and x.empresa_id = bp.empresa_id
       where bp.empresa_id = p_emp and bp.ativo_cardapio and private.maria_norm(btrim(x.nome)) = private.maria_norm(v_nome_busca);
      if v_cnt <> 1 then
        select count(*) into v_cnt from public.bar_produtos bp join public.produtos x on x.id = bp.produto_id and x.empresa_id = bp.empresa_id
         where bp.empresa_id = p_emp and bp.ativo_cardapio and private.maria_norm(x.nome) like v_pad escape '\';
        if v_cnt = 0 then return jsonb_build_object('erro','Produto "' || v_nome_busca || '" não encontrado no cardápio do bar.'); end if;
        if v_cnt > 1 then
          select jsonb_agg(jsonb_build_object('produto', x.nome)) into v_cand from (select x2.nome from public.bar_produtos bp join public.produtos x2 on x2.id = bp.produto_id and x2.empresa_id = bp.empresa_id
            where bp.empresa_id = p_emp and bp.ativo_cardapio and private.maria_norm(x2.nome) like v_pad escape '\' order by x2.nome limit 8) x;
          return jsonb_build_object('ambiguo', true, 'campo', 'produto do pedido', 'candidatos', v_cand);
        end if;
        select bp.id, bp.tipo, x.nome, x.preco_venda into v_bp from public.bar_produtos bp join public.produtos x on x.id = bp.produto_id and x.empresa_id = bp.empresa_id
         where bp.empresa_id = p_emp and bp.ativo_cardapio and private.maria_norm(x.nome) like v_pad escape '\';
      else
        select bp.id, bp.tipo, x.nome, x.preco_venda into v_bp from public.bar_produtos bp join public.produtos x on x.id = bp.produto_id and x.empresa_id = bp.empresa_id
         where bp.empresa_id = p_emp and bp.ativo_cardapio and private.maria_norm(btrim(x.nome)) = private.maria_norm(v_nome_busca);
      end if;
      if v_bp.tipo = 'composto' then return jsonb_build_object('erro','"' || v_bp.nome || '" é um item composto (exige escolhas). Lance esse item pelo app do Bar.'); end if;
      v_itens := v_itens || jsonb_build_array(jsonb_build_object('bar_produto_id', v_bp.id, 'produto', v_bp.nome, 'quantidade', round(num,3),
                         'observacao', private.maria_t(it,'observacao',120,'observação')));
      res := res || E'\n- ' || num || ' x ' || v_bp.nome || ' (' || private.maria_brl(v_bp.preco_venda) || ')';
    end loop;
    n := n || jsonb_build_object('itens', v_itens);
    return jsonb_build_object('params', n, 'resumo', res || E'\nO estoque será baixado normalmente pelo Bar.');
  end if;

  return jsonb_build_object('erro','Ação não reconhecida.');
exception
  when sqlstate 'P0001' then return jsonb_build_object('erro', sqlerrm);
  when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
    return jsonb_build_object('erro','Algum valor informado é inválido.');
end $function$

CREATE OR REPLACE FUNCTION private.maria_config_efetiva(p_empresa uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c public.maria_empresa_config%rowtype;
  pl public.maria_planos%rowtype;
  o jsonb;
begin
  select * into c from public.maria_empresa_config where empresa_id = p_empresa;
  select * into pl from public.maria_planos where codigo = coalesce(c.plano, (select g.plano_padrao from public.maria_config_global g where g.id), 'sem_limite');
  if not found then select * into pl from public.maria_planos where codigo = 'sem_limite'; end if;
  o := coalesce(c.limites_override, '{}'::jsonb);
  return jsonb_build_object(
    'ativa',  coalesce(c.ativa, true),
    'plano',  coalesce(pl.codigo, 'sem_limite'),
    'plano_nome', coalesce(pl.nome, 'Sem limite'),
    'limite_interacoes_mes', case when o ? 'limite_interacoes_mes' then o->'limite_interacoes_mes' else to_jsonb(pl.limite_interacoes_mes) end,
    'limite_tokens_mes',     case when o ? 'limite_tokens_mes'     then o->'limite_tokens_mes'     else to_jsonb(pl.limite_tokens_mes) end,
    'limite_custo_usd_mes',  case when o ? 'limite_custo_usd_mes'  then o->'limite_custo_usd_mes'  else to_jsonb(pl.limite_custo_usd_mes) end,
    'permite_acoes',         case when o ? 'permite_acoes'         then o->'permite_acoes'         else to_jsonb(coalesce(pl.permite_acoes, true)) end,
    'permite_consultoria',   case when o ? 'permite_consultoria'   then o->'permite_consultoria'   else to_jsonb(coalesce(pl.permite_consultoria, true)) end
  );
end $function$

CREATE OR REPLACE FUNCTION private.maria_cpf_valido(p text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d text := regexp_replace(coalesce(p,''), '\D', '', 'g'); s int; i int; r int;
begin
  if length(d) <> 11 or d ~ '^(\d)\1{10}$' then return false; end if;
  s := 0; for i in 1..9 loop s := s + substr(d,i,1)::int * (11 - i); end loop;
  r := (s * 10) % 11; if r = 10 then r := 0; end if; if r <> substr(d,10,1)::int then return false; end if;
  s := 0; for i in 1..10 loop s := s + substr(d,i,1)::int * (12 - i); end loop;
  r := (s * 10) % 11; if r = 10 then r := 0; end if; return r = substr(d,11,1)::int;
end $function$

CREATE OR REPLACE FUNCTION private.maria_d(p jsonb, k text, label text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text;
begin
  if p is null or not (p ? k) or jsonb_typeof(p->k) = 'null' then return null; end if;
  v := btrim(p->>k);
  if v = '' then return null; end if;
  if v ~ '^\d{2}/\d{2}/\d{4}$' then return to_date(v, 'DD/MM/YYYY'); end if;
  if v !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'A data de % é inválida (use dia/mês/ano).', label; end if;
  return v::date;
exception when datetime_field_overflow or invalid_datetime_format then
  raise exception 'A data de % é inválida.', label;
end $function$

CREATE OR REPLACE FUNCTION private.maria_digitos(p jsonb, k text, rotulo text, tams integer[], preencher boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text; v_min integer := (select min(t) from unnest(tams) t);
begin
  v := private.maria_t(p, k, 40, rotulo);
  if v is null then return null; end if;
  v := regexp_replace(v, '[.\-/\s]', '', 'g');
  if v !~ '^[0-9]+$' then raise exception 'O % informado é inválido: use apenas números.', rotulo; end if;
  if preencher and length(v) < v_min then v := lpad(v, v_min, '0'); end if;
  if not (length(v) = any(tams)) then
    raise exception 'O % informado é inválido: deve ter % dígitos (veio com %).', rotulo, array_to_string(tams, ' ou '), length(v); end if;
  return v;
end $function$

CREATE OR REPLACE FUNCTION private.maria_exigir_servidor()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hdr text; v_seg text; v_hash text;
begin
  begin v_hdr := nullif(current_setting('request.headers', true), '');
  exception when others then v_hdr := null; end;
  if v_hdr is not null then
    begin v_seg := (v_hdr::jsonb) ->> 'x-maria-secret';
    exception when others then v_seg := null; end;
  end if;
  select s.hash_sha256 into v_hash from private.maria_segredo_servidor s where s.id;
  if v_hash is null or v_seg is null or length(v_seg) < 32
     or encode(sha256(convert_to(v_seg, 'UTF8')), 'hex') <> v_hash then
    raise exception 'MARIA_NAO_AUTORIZADA' using errcode = '42501';
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.maria_gtin_valido(p text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d text := coalesce(p,''); n int; i int; s int := 0; w int;
begin
  if d !~ '^\d+$' or length(d) not in (8,12,13,14) then return false; end if;
  n := length(d);
  for i in 1..n-1 loop
    w := case when ((n - i) % 2) = 1 then 3 else 1 end;
    s := s + substr(d,i,1)::int * w;
  end loop;
  return ((10 - (s % 10)) % 10) = substr(d,n,1)::int;
end $function$

CREATE OR REPLACE FUNCTION private.maria_interpretar_resposta(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare n text := btrim(regexp_replace(regexp_replace(private.maria_norm(p), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'));
begin
  -- Vocabulário propositalmente curto: palavras ambíguas ("ok", "certo", "isso", "vai"...) NÃO confirmam.
  if n in ('sim','confirmo','confirmar','confirma','sim confirmo','pode confirmar','sim pode confirmar') then return 'confirmar'; end if;
  if n in ('nao','cancela','cancelar','cancele','nao confirmo','nao quero','desisto','desisti') then return 'cancelar'; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.maria_n(p jsonb, k text, lo numeric, hi numeric, label text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text; n numeric;
begin
  if p is null or not (p ? k) or jsonb_typeof(p->k) = 'null' then return null; end if;
  if jsonb_typeof(p->k) not in ('string','number') then raise exception 'O valor informado para % é inválido.', label; end if;
  v := btrim(p->>k);
  if v = '' then return null; end if;
  v := regexp_replace(v, '^R\$\s*', '');
  if v ~ '^-?[0-9]{1,3}(\.[0-9]{3})+,[0-9]+$' then v := replace(replace(v, '.', ''), ',', '.');   -- 1.234,56
  elsif v ~ '^-?[0-9]+,[0-9]+$' then v := replace(v, ',', '.'); end if;                             -- 12,5
  if v !~ '^-?[0-9]+(\.[0-9]+)?$' or length(v) > 18 then raise exception 'O valor informado para % é inválido.', label; end if;
  n := v::numeric;
  if n < lo or n > hi then raise exception 'O valor informado para % está fora do permitido (de % a %).', label, lo, hi; end if;
  return n;
end $function$

CREATE OR REPLACE FUNCTION private.maria_periodo(p_inicio date, p_fim date, p_default_dias integer DEFAULT 0, OUT o_ini date, OUT o_fim date)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  if p_inicio is null and p_fim is null then
    if p_default_dias > 0 then o_ini := v_hoje - (p_default_dias - 1); o_fim := v_hoje;
    else o_ini := date_trunc('month', v_hoje)::date; o_fim := v_hoje; end if;
  else
    o_ini := coalesce(p_inicio, p_fim);
    o_fim := coalesce(p_fim, v_hoje);
    if p_inicio is null then o_ini := o_fim - 29; end if;
  end if;
  if o_fim < o_ini then raise exception 'A data final não pode ser anterior à data inicial.'; end if;
  if o_fim - o_ini > 731 then raise exception 'Período máximo de 2 anos por consulta.'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.maria_prod_campos(p_emp uuid, p jsonb, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o jsonb := '{}'::jsonb; s text; num numeric; v_nome text; d text;
begin
  s := private.maria_t(p,'nome',200,'nome do produto');
  if s is not null then o := o || jsonb_build_object('nome', s); end if;

  s := private.maria_t(p,'codigo',60,'código');
  if s is not null then
    select x.nome into v_nome from public.produtos x where x.empresa_id = p_emp and x.codigo = s and (p_id is null or x.id <> p_id) limit 1;
    if found then raise exception 'Já existe um produto com esse código: “%”.', v_nome; end if;
    o := o || jsonb_build_object('codigo', s);
  end if;

  s := private.maria_t(p,'gtin',40,'código de barras');
  if s is not null then
    d := regexp_replace(s, '[\s.\-]', '', 'g');
    if d !~ '^[0-9]+$' then raise exception 'O código de barras (GTIN) informado é inválido: use apenas números.'; end if;
    if length(d) not in (8,12,13,14) then
      raise exception 'O código de barras (GTIN) informado é inválido: tem % dígitos (esperado 8, 12, 13 ou 14).', length(d); end if;
    if not private.maria_gtin_valido(d) then raise exception 'O código de barras (GTIN) informado é inválido: dígito verificador incorreto.'; end if;
    select x.nome into v_nome from public.produtos x where x.empresa_id = p_emp and (p_id is null or x.id <> p_id)
       and nullif(ltrim(x.gtin,'0'),'') = nullif(ltrim(d,'0'),'') limit 1;
    if found then raise exception 'Já existe um produto com esse código de barras: “%”.', v_nome; end if;
    o := o || jsonb_build_object('gtin', d);
  end if;

  s := private.maria_t(p,'unidade_comercial',20,'unidade');
  if s is not null then
    s := upper(regexp_replace(private.maria_norm(s), '\s', '', 'g'));
    s := case s when 'UNID' then 'UN' when 'UNIDADE' then 'UN' when 'UND' then 'UN' when 'UNIDADES' then 'UN'
                when 'CAIXA' then 'CX' when 'CAIXAS' then 'CX' when 'CXA' then 'CX'
                when 'FARDO' then 'FD' when 'FARDOS' then 'FD' when 'FDO' then 'FD'
                when 'PACOTE' then 'PCT' when 'PACOTES' then 'PCT'
                when 'LITRO' then 'L' when 'LITROS' then 'L'
                when 'QUILO' then 'KG' when 'QUILOS' then 'KG' when 'KILO' then 'KG' else s end;
    if length(s) > 6 then raise exception 'A unidade informada é longa demais (máximo 6 caracteres).'; end if;
    o := o || jsonb_build_object('unidade_comercial', s);
  end if;

  s := private.maria_t(p,'categoria',80,'categoria');
  if s is not null then o := o || jsonb_build_object('categoria', s); end if;

  num := private.maria_n(p,'preco_venda',0,9999999.99,'preço de venda');
  if num is not null then o := o || jsonb_build_object('preco_venda', round(num,2)); end if;
  num := private.maria_n(p,'preco_custo',0,9999999.99,'preço de custo');
  if num is not null then o := o || jsonb_build_object('preco_custo', round(num,4)); end if;
  num := private.maria_n(p,'estoque_minimo',0,10000000,'estoque mínimo');
  if num is not null then o := o || jsonb_build_object('estoque_minimo', round(num,4)); end if;

  s := private.maria_t(p,'tipo_fiscal',20,'tipo fiscal');
  if s is not null then
    s := private.maria_norm(s);
    if s not in ('produto','servico') then raise exception 'O tipo fiscal deve ser "produto" ou "serviço".'; end if;
    o := o || jsonb_build_object('tipo_fiscal', s);
  end if;

  -- Dados fiscais: só gravados se o usuário informar; formato idêntico ao do importador de produtos.
  s := private.maria_digitos(p,'ncm','NCM',array[8]);                          if s is not null then o := o || jsonb_build_object('ncm', s); end if;
  s := private.maria_digitos(p,'cest','CEST',array[7]);                        if s is not null then o := o || jsonb_build_object('cest', s); end if;
  s := private.maria_digitos(p,'cfop','CFOP',array[4]);                        if s is not null then o := o || jsonb_build_object('cfop', s); end if;
  s := private.maria_t(p,'origem_mercadoria',40,'origem da mercadoria');
  if s is not null then
    if s ~ '^[0-8]\s*(-.*)?$' then o := o || jsonb_build_object('origem_mercadoria', substr(s,1,1));
    else raise exception 'A origem da mercadoria informada é inválida: use um dígito de 0 a 8 (ex.: 0 = nacional).'; end if;
  end if;
  s := private.maria_digitos(p,'cst_csosn','CST/CSOSN',array[2,3],true);       if s is not null then o := o || jsonb_build_object('cst_csosn', s); end if;
  num := private.maria_n(p,'aliquota_icms',0,100,'alíquota de ICMS');
  if num is not null then o := o || jsonb_build_object('aliquota_icms', round(num,4)); end if;
  s := private.maria_digitos(p,'cst_pis','CST PIS',array[2],true);             if s is not null then o := o || jsonb_build_object('cst_pis', s); end if;
  s := private.maria_digitos(p,'cst_cofins','CST COFINS',array[2],true);       if s is not null then o := o || jsonb_build_object('cst_cofins', s); end if;
  -- Campos de serviço (tela de cadastro: texto livre / ISS em %)
  s := private.maria_t(p,'codigo_servico',60,'código do serviço');                          if s is not null then o := o || jsonb_build_object('codigo_servico', s); end if;
  s := private.maria_t(p,'codigo_tributacao_municipal',60,'código de tributação municipal'); if s is not null then o := o || jsonb_build_object('codigo_tributacao_municipal', s); end if;
  s := private.maria_t(p,'municipio_incidencia',80,'município de incidência');            if s is not null then o := o || jsonb_build_object('municipio_incidencia', s); end if;
  num := private.maria_n(p,'iss',0,100,'ISS');
  if num is not null then o := o || jsonb_build_object('iss', round(num,4)); end if;
  return o;
end $function$

CREATE OR REPLACE FUNCTION private.maria_prod_fmt(k text, v text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text; ip text; fp text;
begin
  if v is null or v = '' then return '(vazio)'; end if;
  if k in ('preco_venda','preco_custo') then
    s := to_char(v::numeric, 'FM999999999990.0000'); ip := split_part(s, '.', 1); fp := rpad(rtrim(split_part(s, '.', 2), '0'), 2, '0');
    return 'R$ ' || ip || ',' || fp;
  elsif k in ('aliquota_icms','iss','estoque_minimo') then
    s := to_char(v::numeric, 'FM9999999990.0000'); ip := split_part(s, '.', 1); fp := rtrim(split_part(s, '.', 2), '0');
    return ip || case when fp <> '' then ',' || fp else '' end || case when k = 'estoque_minimo' then '' else '%' end;
  elsif k = 'tipo_fiscal' then return case v when 'servico' then 'Serviço' else 'Produto' end;
  end if;
  return v;
end $function$

CREATE OR REPLACE FUNCTION private.maria_resolver_cliente(p_emp uuid, p_id uuid, p_busca text, OUT o_id uuid, OUT o_candidatos jsonb)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_n integer; v_pad text := private.maria_like(p_busca); v_ex text := private.maria_norm(btrim(coalesce(p_busca,'')));
begin
  o_id := null; o_candidatos := null;
  if p_id is not null then
    select c.id into o_id from public.clientes c where c.id = p_id and c.empresa_id = p_emp;
    return;
  end if;
  if length(btrim(coalesce(p_busca,''))) < 2 then return; end if;
  -- 1) igualdade exata (sem acento/caixa)
  select count(*) into v_n from public.clientes c where c.empresa_id = p_emp and private.maria_norm(btrim(c.nome)) = v_ex;
  if v_n = 1 then select c.id into o_id from public.clientes c where c.empresa_id = p_emp and private.maria_norm(btrim(c.nome)) = v_ex; return; end if;
  if v_n > 1 then
    select jsonb_agg(jsonb_build_object('id', c.id, 'nome', c.nome, 'telefone', c.telefone, 'cidade', c.cidade)) into o_candidatos
      from (select * from public.clientes c where c.empresa_id = p_emp and private.maria_norm(btrim(c.nome)) = v_ex order by c.nome limit 8) c;
    return;
  end if;
  -- 2) contém
  select count(*) into v_n from public.clientes c where c.empresa_id = p_emp and private.maria_norm(c.nome) like v_pad escape '\';
  if v_n = 1 then select c.id into o_id from public.clientes c where c.empresa_id = p_emp and private.maria_norm(c.nome) like v_pad escape '\'; return; end if;
  if v_n > 1 then
    select jsonb_agg(jsonb_build_object('id', c.id, 'nome', c.nome, 'telefone', c.telefone, 'cidade', c.cidade)) into o_candidatos
      from (select * from public.clientes c where c.empresa_id = p_emp and private.maria_norm(c.nome) like v_pad escape '\' order by c.nome limit 8) c;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.maria_resolver_produto(p_emp uuid, p_id uuid, p_busca text, OUT o_id uuid, OUT o_candidatos jsonb)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_n integer; v_pad text := private.maria_like(p_busca); v_ex text := private.maria_norm(btrim(coalesce(p_busca,'')));
        v_raw text := btrim(coalesce(p_busca,''));
begin
  o_id := null; o_candidatos := null;
  if p_id is not null then
    select p.id into o_id from public.produtos p where p.id = p_id and p.empresa_id = p_emp; return;
  end if;
  if length(v_raw) < 2 then return; end if;
  -- código interno / GTIN exatos
  select count(*) into v_n from public.produtos p where p.empresa_id = p_emp and (p.codigo = v_raw or p.gtin = v_raw);
  if v_n = 1 then select p.id into o_id from public.produtos p where p.empresa_id = p_emp and (p.codigo = v_raw or p.gtin = v_raw); return; end if;
  -- nome exato
  select count(*) into v_n from public.produtos p where p.empresa_id = p_emp and private.maria_norm(btrim(p.nome)) = v_ex;
  if v_n = 1 then select p.id into o_id from public.produtos p where p.empresa_id = p_emp and private.maria_norm(btrim(p.nome)) = v_ex; return; end if;
  if v_n > 1 then
    select jsonb_agg(jsonb_build_object('id', q.id, 'nome', q.nome, 'codigo', q.codigo, 'preco_venda', q.preco_venda, 'estoque', q.quantidade_estoque)) into o_candidatos
      from (select * from public.produtos p where p.empresa_id = p_emp and private.maria_norm(btrim(p.nome)) = v_ex order by p.nome limit 8) q;
    return;
  end if;
  -- contém
  select count(*) into v_n from public.produtos p where p.empresa_id = p_emp and private.maria_norm(p.nome) like v_pad escape '\';
  if v_n = 1 then select p.id into o_id from public.produtos p where p.empresa_id = p_emp and private.maria_norm(p.nome) like v_pad escape '\'; return; end if;
  if v_n > 1 then
    select jsonb_agg(jsonb_build_object('id', q.id, 'nome', q.nome, 'codigo', q.codigo, 'preco_venda', q.preco_venda, 'estoque', q.quantidade_estoque)) into o_candidatos
      from (select * from public.produtos p where p.empresa_id = p_emp and private.maria_norm(p.nome) like v_pad escape '\' order by p.nome limit 8) q;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.maria_scrub(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text; v jsonb; r jsonb;
begin
  if p is null then return null; end if;
  if jsonb_typeof(p) = 'object' then
    r := '{}'::jsonb;
    for k, v in select * from jsonb_each(p) loop
      if k ~* '(jwt|(^|_)token($|_)|secret|senha|password|passwd|authorization|api[_-]?key|certificad|pfx|cpf_cnpj_senha)' then
        continue;
      end if;
      if lower(k) = 'cpf' and jsonb_typeof(v) = 'string' then   -- LGPD: a auditoria é imutável, então só guarda o final do CPF
        r := r || jsonb_build_object(k, '***' || right(regexp_replace(v #>> '{}', '\D', '', 'g'), 2));
        continue;
      end if;
      r := r || jsonb_build_object(k, private.maria_scrub(v));
    end loop;
    return r;
  elsif jsonb_typeof(p) = 'array' then
    select coalesce(jsonb_agg(private.maria_scrub(e)), '[]'::jsonb) into r from jsonb_array_elements(p) e;
    return r;
  end if;
  return p;
end $function$

CREATE OR REPLACE FUNCTION private.maria_t(p jsonb, k text, maxlen integer, label text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text;
begin
  if p is null or not (p ? k) or jsonb_typeof(p->k) = 'null' then return null; end if;
  if jsonb_typeof(p->k) not in ('string','number') then raise exception 'O campo % é inválido.', label; end if;
  v := btrim(regexp_replace(p->>k, '[[:cntrl:]]', ' ', 'g'));
  v := regexp_replace(v, '\s{2,}', ' ', 'g');
  if v = '' then return null; end if;
  if length(v) > maxlen then raise exception 'O campo % é longo demais (máximo % caracteres).', label, maxlen; end if;
  return v;
end $function$

CREATE OR REPLACE FUNCTION private.maria_u(p jsonb, k text, label text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text;
begin
  if p is null or not (p ? k) or jsonb_typeof(p->k) = 'null' then return null; end if;
  v := btrim(p->>k);
  if v = '' then return null; end if;
  if v !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'O identificador de % é inválido.', label; end if;
  return v::uuid;
end $function$

